from collections import deque

def transform(grid):
    h, w = len(grid), len(grid[0])
    seen = set()
    objects = []
    for r in range(h):
        for c in range(w):
            color = grid[r][c]
            if color == 0 or (r, c) in seen:
                continue
            cells = set()
            q = deque([(r, c)])
            seen.add((r, c))
            while q:
                y, x = q.popleft()
                cells.add((y, x))
                for ny, nx in ((y-1,x),(y+1,x),(y,x-1),(y,x+1)):
                    if 0 <= ny < h and 0 <= nx < w and (ny,nx) not in seen and grid[ny][nx] == color:
                        seen.add((ny,nx))
                        q.append((ny,nx))
            objects.append((color, cells))
    reference = next(cells for color, cells in objects if color == 8)
    def normalize(cells):
        top = min(r for r, c in cells)
        left = min(c for r, c in cells)
        return frozenset((r-top, c-left) for r, c in cells)
    target = normalize(reference)
    out = [row[:] for row in grid]
    for color, cells in objects:
        if color != 8 and normalize(cells) == target:
            for r, c in cells:
                out[r][c] = 8
    return out
